CREATE DATABASE IF NOT EXISTS passnow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE passnow;
CREATE TABLE organizations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_user_org_email(organization_id,email),KEY idx_users_org(organization_id),CONSTRAINT fk_users_org FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,description VARCHAR(255) NULL,module VARCHAR(80) NOT NULL,action VARCHAR(80) NOT NULL,is_system BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL);
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,code VARCHAR(100) NOT NULL,is_system BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_role_org_code(organization_id,code),CONSTRAINT fk_roles_org FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE user_roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,organization_id BIGINT UNSIGNED NOT NULL,scope_type VARCHAR(30) NOT NULL DEFAULT 'ORGANIZATION',site_id BIGINT UNSIGNED NULL,gate_id BIGINT UNSIGNED NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_user_roles_user_org(user_id,organization_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE sites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,code VARCHAR(80) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_site_org_code(organization_id,code),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE gates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,site_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,code VARCHAR(80) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_gate_org_code(organization_id,code),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(site_id) REFERENCES sites(id));
CREATE TABLE visitors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,phone VARCHAR(40) NULL,email VARCHAR(255) NULL,is_blacklisted BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_visitors_org(organization_id),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE pass_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,code VARCHAR(80) NOT NULL,requires_approval BOOLEAN NOT NULL DEFAULT TRUE,validity_minutes INT UNSIGNED NOT NULL DEFAULT 480,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_pass_type_org_code(organization_id,code),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
CREATE TABLE gatepasses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,visitor_id BIGINT UNSIGNED NOT NULL,gate_id BIGINT UNSIGNED NOT NULL,pass_type_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL,valid_from DATETIME NOT NULL,valid_until DATETIME NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_gatepasses_org_status(organization_id,status),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(visitor_id) REFERENCES visitors(id),FOREIGN KEY(gate_id) REFERENCES gates(id),FOREIGN KEY(pass_type_id) REFERENCES pass_types(id));
CREATE TABLE approval_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,gatepass_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL,step_order INT UNSIGNED NOT NULL,acted_by BIGINT UNSIGNED NULL,acted_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(gatepass_id) REFERENCES gatepasses(id) ON DELETE CASCADE,FOREIGN KEY(acted_by) REFERENCES users(id));
CREATE TABLE credentials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,gatepass_id BIGINT UNSIGNED NOT NULL,token CHAR(36) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,is_revoked BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(gatepass_id) REFERENCES gatepasses(id) ON DELETE CASCADE);
CREATE TABLE check_ins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,gatepass_id BIGINT UNSIGNED NOT NULL,gate_id BIGINT UNSIGNED NOT NULL,checked_in_by BIGINT UNSIGNED NULL,checked_in_at DATETIME NOT NULL,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(gatepass_id) REFERENCES gatepasses(id),FOREIGN KEY(gate_id) REFERENCES gates(id),FOREIGN KEY(checked_in_by) REFERENCES users(id));
CREATE TABLE check_outs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,gatepass_id BIGINT UNSIGNED NOT NULL,gate_id BIGINT UNSIGNED NOT NULL,checked_out_by BIGINT UNSIGNED NULL,checked_out_at DATETIME NOT NULL,FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(gatepass_id) REFERENCES gatepasses(id),FOREIGN KEY(gate_id) REFERENCES gates(id),FOREIGN KEY(checked_out_by) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NULL,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,resource_type VARCHAR(80) NOT NULL,resource_id BIGINT UNSIGNED NULL,old_values JSON NULL,new_values JSON NULL,created_at DATETIME NOT NULL,KEY idx_audit_org_created(organization_id,created_at),KEY idx_audit_resource(resource_type,resource_id),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE SET NULL,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE organization_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,setting_key VARCHAR(120) NOT NULL,setting_value JSON NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_org_setting(organization_id,setting_key),FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE);
